const scenarios = {
  "echo": `
    const log = [], server = dgram.createSocket("udp4"), client = dgram.createSocket("udp4");
    server.on("listening", () => log.push("server listening")); server.on("close", () => log.push("server close"));
    client.on("listening", () => { const a = client.address(); log.push("client listening " + a.address + " " + a.family); }); client.on("close", () => log.push("client close"));
    const done = new Promise(resolve => client.on("message", (msg, rinfo) => { log.push(["client message", msg.toString(), Buffer.isBuffer(msg), Object.keys(rinfo), rinfo.address, rinfo.family, rinfo.port === server.address().port, rinfo.size]); resolve(); }));
    server.on("message", (msg, rinfo) => { log.push(["server message", msg.toString(), rinfo.address, rinfo.family, rinfo.port === client.address().port, rinfo.size]); server.send("pong:" + msg, rinfo.port, rinfo.address, (error, bytes) => log.push(["server sent", error, bytes])); });
    server.bind(0, "127.0.0.1", function () { log.push("server bind callback " + (this === server)); });
    await once(server, "listening");
    log.push("sending");
    client.send("ping", server.address().port, "127.0.0.1", function (error, bytes) { log.push(["client sent", error, bytes, this === client]); });
    log.push("send returned");
    await done; await turn();
    client.close(() => log.push("client close callback")); log.push("client close returned");
    await once(client, "close");
    server.close(); await once(server, "close");
    return log;`,
  "ordering of three datagrams": `
    const log = [], server = await bound(), client = dgram.createSocket("udp4");
    const got = new Promise(resolve => server.on("message", msg => { log.push(msg.toString()); if (log.length === 3) resolve(); }));
    for (const text of ["one", "two", "three"]) client.send(text, server.address().port, "127.0.0.1");
    await got; await closed(client); await closed(server); return log;`,
  "send overloads": `
