    const sent = async run => { const arrived = next(); const callback = new Promise(resolve => run((error, bytes) => resolve([error, bytes]))); log.push([await arrived, await callback]); };
    await sent(cb => client.send("string", port, "127.0.0.1", cb));
    await sent(cb => client.send(Buffer.from("buffer"), port, "127.0.0.1", cb));
