const shape = error => error instanceof Error ? Object.fromEntries([["name", error.name], ["message", error.message], ...["code", "errno", "syscall", "address", "port"].filter(key => key in error).map(key => [key, error[key]])]) : { thrown: String(error) };
const fail = run => { try { return { returned: run() === undefined ? "undefined" : "value" }; } catch (error) { return shape(error); } };
const once = (emitter, event) => new Promise(resolve => emitter.once(event, (...args) => resolve(args)));
const bound = async (type = "udp4", address = type === "udp4" ? "127.0.0.1" : "::1") => { const socket = dgram.createSocket(type); socket.bind(0, address); await once(socket, "listening"); return socket; };
const closed = async socket => { const done = once(socket, "close"); socket.close(); await done; };
const turn = () => new Promise(resolve => setImmediate(resolve));

